        "code": "def evaluate_sec270aa_immunity(is_misreporting: bool, demand_paid_within_time: bool, appeal_waived: bool, form68_filed_within_1m: bool) -> dict:\n    if is_misreporting:\n        return {\n            \"immunity_granted\": False,\n            \"status\": \"BARRED under Sec 270AA(3): Immunity cannot be granted for cases involving Section 270A(8)/(9) Misreporting\"\n        }\n        \n    conditions_met = demand_paid_within_time and appeal_waived and form68_filed_within_1m\n    \n    if conditions_met:\n        return {\n            \"immunity_granted\": True,\n            \"status\": \"IMMUNITY GRANTED under Section 270AA(4)\",\n            \"benefits\": [\n                \"100% waiver of penalty under Section 270A\",\n                \"Total immunity from prosecution under Section 276C / 276CCC\",\n                \"Final settlement and closure of assessment\"\n            ]\n        }\n    else:\n        reasons = []\n        if not demand_paid_within_time:\n            reasons.append(\"Demand not paid within 30-day window\")\n        if not appeal_waived:\n            reasons.append(\"Appeal filed before CIT(Appeals)\")\n        if not form68_filed_within_1m:\n            reasons.append(\"Form 68 not filed within 1 month\")\n        return {\n            \"immunity_granted\": False,\n            \"status\": f\"REJECTED: Preconditions violated ({', '.join(reasons)})\"\n        }\n\nimm_res = evaluate_sec270aa_immunity(is_misreporting=False, demand_paid_within_time=True, appeal_waived=True, form68_filed_within_1m=True)\nprint(f\"Immunity Granted: {imm_res['immunity_granted']}\")\nprint(f\"Outcome: {imm_res['status']}\")\nif imm_res['immunity_granted']:\n    for b in imm_res['benefits']:\n        print(f\"  -> {b}\")\n",
